import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Send, Sparkles, Scroll, Zap } from 'lucide-react';
import { chatWithAmeyAI } from '../services/geminiService';
import { ChatMessage } from '../types';

export const AIChat: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: "Greetings. I am Amey's digital shadow. Summon me for knowledge about his skills and experience." }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userText = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userText }]);
    setIsLoading(true);

    try {
      const responseText = await chatWithAmeyAI(userText);
      setMessages(prev => [...prev, { role: 'model', text: responseText }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "The connection was severed. Please try again.", isError: true }]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-50 flex flex-col items-end">
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, scale: 0.8, y: 50, rotateX: 90 }}
            animate={{ opacity: 1, scale: 1, y: 0, rotateX: 0 }}
            exit={{ opacity: 0, scale: 0.8, y: 50, rotateX: 90 }}
            transition={{ type: "spring", duration: 0.5 }}
            className="mb-4 w-[90vw] max-w-[350px] sm:w-[380px] bg-[#0a0a0a] border-2 border-naruto/50 rounded-lg shadow-[0_0_30px_rgba(255,153,0,0.3)] overflow-hidden flex flex-col h-[550px] relative"
          >
            {/* Forbidden Scroll Texture */}
            <div className="absolute inset-0 pointer-events-none opacity-5 bg-[url('https://www.transparenttextures.com/patterns/rice-paper.png')]"></div>

            {/* Header - Ninja Headband Plate Style */}
            <div className="bg-[#111] p-4 border-b-2 border-naruto/30 flex justify-between items-center relative z-10">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-full bg-naruto/20 border border-naruto flex items-center justify-center animate-pulse-fast">
                  <Scroll size={20} className="text-naruto" />
                </div>
                <div>
                  <h3 className="font-manga text-white text-lg tracking-wider text-shadow-glow">KAGE ASSISTANT</h3>
                  <p className="text-[10px] text-naruto font-mono uppercase">Summoned via Gemini 2.5</p>
                </div>
              </div>
              <button 
                onClick={() => setIsOpen(false)}
                className="text-slate-500 hover:text-white transition-colors"
              >
                <X size={20} />
              </button>
            </div>

            {/* Messages Area */}
            <div className="flex-1 overflow-y-auto p-4 space-y-4 scrollbar-hide bg-[#050505] relative">
              {/* Vertical Writing Decoration */}
              <div className="absolute top-4 right-2 text-[10px] font-mono text-white/5 writing-vertical-rl pointer-events-none">
                 SECRET SCROLL // FORBIDDEN JUTSU
              </div>

              {messages.map((msg, idx) => (
                <motion.div 
                  initial={{ opacity: 0, x: msg.role === 'user' ? 20 : -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  key={idx} 
                  className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
                >
                  <div 
                    className={`max-w-[85%] p-4 text-sm leading-relaxed relative ${
                      msg.role === 'user' 
                        ? 'bg-naruto text-black font-bold clip-path-speech-right' 
                        : 'bg-slate-900 border border-slate-700 text-slate-200 clip-path-speech-left'
                    }`}
                    style={{
                        clipPath: msg.role === 'user' 
                            ? 'polygon(100% 0, 100% 100%, 0 100%, 0 15px, 15px 0)' 
                            : 'polygon(100% 0, 100% 85%, 85% 100%, 0 100%, 0 0)'
                    }}
                  >
                    {msg.text}
                  </div>
                </motion.div>
              ))}
              {isLoading && (
                <div className="flex justify-start">
                  <div className="bg-slate-900 border border-slate-700 p-3 flex items-center gap-2 clip-path-speech-left" style={{ clipPath: 'polygon(100% 0, 100% 85%, 85% 100%, 0 100%, 0 0)' }}>
                    <Zap size={16} className="animate-spin text-naruto" />
                    <span className="text-xs text-naruto font-mono animate-pulse">Weaving signs...</span>
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </div>

            {/* Input Area */}
            <div className="p-3 bg-[#111] border-t border-naruto/30 relative z-10">
              <div className="relative">
                <input
                  type="text"
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={handleKeyDown}
                  placeholder="Type your query..."
                  className="w-full bg-black border border-slate-700 text-white py-3 pl-4 pr-12 focus:outline-none focus:border-naruto transition-colors text-sm font-mono placeholder:text-slate-600"
                  style={{ borderRadius: '0px' }}
                />
                <button
                  onClick={handleSend}
                  disabled={isLoading || !input.trim()}
                  className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 text-naruto hover:text-white disabled:opacity-50"
                >
                  <Send size={18} />
                </button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Launcher Button - Summoning Circle Style */}
      <motion.button
        whileHover={{ scale: 1.1, rotate: 180 }}
        whileTap={{ scale: 0.9 }}
        onClick={() => setIsOpen(!isOpen)}
        className="w-16 h-16 bg-gradient-to-br from-red-600 to-red-900 rounded-full flex items-center justify-center shadow-[0_0_20px_rgba(220,38,38,0.5)] text-white relative group z-50 border-2 border-black"
      >
        <div className="absolute inset-1 border border-dashed border-white/50 rounded-full animate-spin-slow"></div>
        <AnimatePresence mode='wait'>
          {isOpen ? (
             <X size={28} key="close" />
          ) : (
             <Scroll size={28} key="open" className="group-hover:text-black transition-colors" />
          )}
        </AnimatePresence>

        {/* Chakra Pulse */}
        <span className="absolute -inset-2 rounded-full border border-red-500/50 animate-ping -z-10"></span>
      </motion.button>
    </div>
  );
};

